#!/usr/bin/env node
// Pin git's core.hooksPath to the root-owned, entire-proof hook entrypoints
// baked into the dev container image (.devcontainer/Dockerfile -> /opt/githooks).
//
// WHY: husky's `prepare` lifecycle resets core.hooksPath to the
// entire-clobberable `.husky/_` on EVERY `pnpm install`. This script runs
// immediately after `husky` in the `prepare` chain (see package.json) and
// re-pins the pointer, so the deterministic quality gate survives every
// dependency install inside the container — not only the initial
// postCreateCommand. The entrypoints themselves are root:root mode-0555, so
// once git points at them `entire` (running as the unprivileged `vscode` user)
// physically cannot clobber the gate. See LOCAL_CI_PARITY_INVARIANTS.md row 7f.
//
// SCOPE: dev container only. No-op anywhere the baked entrypoints are absent
// (CI runners, native clones) — those keep husky's `.husky/_` path, where the
// in-hook dispatcher self-heal (scripts/run_repo_hook.py) is the backstop.
//
// SAFETY: this MUST NOT fail `pnpm install`. A pin failure degrades to the
// in-hook re-assertion (ensure_hooks_path) and CI; it never blocks setup.
//
// ADO_GITHOOKS_DIR overrides the baked path for tests/CI determinism checks
// only; production never sets it.
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");

const hooksDir = process.env.ADO_GITHOOKS_DIR || "/opt/githooks";

try {
  // Require the actual entrypoint, not merely the directory, so a stale or
  // empty dir never repoints git at a non-functional hooks path.
  if (!fs.existsSync(path.join(hooksDir, "pre-commit"))) {
    process.exit(0); // not the dev container — leave husky's .husky/_ in place
  }
  execFileSync("git", ["config", "core.hooksPath", hooksDir], {
    stdio: ["ignore", "ignore", "inherit"],
  });
  console.log(`[prepare] pinned core.hooksPath -> ${hooksDir} (entire-proof gate)`);
} catch (err) {
  // Never break the install; the in-hook re-assertion and CI remain backstops.
  console.warn(
    `[prepare] WARNING: could not pin core.hooksPath: ${err && err.message}`,
  );
}
process.exit(0);

